const plannedListURL = "https://pcpartpicker.com/list/abc123"

// pcppPaste builds a list's Markup > Text from its part lines.
func pcppPaste(listURL string, parts ...string) string {
	return "PCPartPicker Part List: " + listURL + "\n\n" + strings.Join(parts, "\n") +
		"\nTotal: $0.00\nGenerated by PCPartPicker 2026-10-02 21:28 EDT-0400\n"
}

var plannedList = pcppPaste(plannedListURL,
	"CPU: Ryzen 7 9800X3D  ($449.00 @ Amazon)",
	"Video Card: Radeon RX 9070 XT  ($649.99 @ Amazon)",
	"Storage: Samsung 990 Pro 2 TB  ($169.99 @ Amazon)",
	"Storage: Samsung 990 Pro 2 TB  ($169.99 @ Amazon)",
)

// importPlanned imports the planned list into a new machine as the user's
// not-yet-bought parts and returns the machine ID.
func (app *testApp) importPlanned(cookie *http.Cookie) int64 {
	app.t.Helper()
	rr := app.post(cookie, "/import", url.Values{
		"pcpartpicker_text": {plannedList},
		"machine_name":      {"Planned"},
		"wanted":            {"on"},
	})
	assertStatus(app.t, rr, http.StatusSeeOther)
	machines, err := app.queries.ListMachines(app.t.Context())
	if err != nil {
		app.t.Fatal(err)
	}
	for _, m := range machines {
		if m.Machine.Name == "Planned" {
			return m.Machine.ID
		}
	}
	app.t.Fatal("import made no Planned machine")
	return 0
}

// updatePrices pastes a list into the machine's price update form.
func (app *testApp) updatePrices(cookie *http.Cookie, machineID int64, list string) *httptest.ResponseRecorder {
	app.t.Helper()
	return app.post(cookie, machinePath(machineID, "/prices"), url.Values{"list": {list}})
}

// partsNamed returns a user's parts with the given name, oldest first.
func (app *testApp) partsNamed(username, name string) []db.Part {
	app.t.Helper()
	var out []db.Part
	for _, p := range app.ownedParts(username) {
		if p.Name == name {
			out = append(out, p)
		}
	}
	slices.SortFunc(out, func(a, b db.Part) int { return int(a.ID - b.ID) })
	return out
}

// slotOf returns the ID of the slot holding the named part.
func slotOf(t *testing.T, slots []db.ListSlotsByMachineRow, partName string) int64 {
	t.Helper()
	for _, s := range slots {
		if s.PartName.String == partName {
			return s.ID
		}
	}
	t.Fatalf("no slot holds %q", partName)
	return 0
}

func TestUpdatePrices(t *testing.T) {
	app := newTestApp(t)
	alice := app.login("alice")
	machineID := app.importPlanned(alice)

	// Alice buys the GPU for less than the list said.
	gpuSlot := slotOf(t, app.slots(machineID), "Radeon RX 9070 XT")
	rr := app.post(alice, slotPath(gpuSlot, "/part/bought"), url.Values{"price": {"$599.00"}})
	assertStatus(t, rr, http.StatusSeeOther)

	// Prices drop, and one of the two SSDs comes off the list.
	rr = app.updatePrices(alice, machineID, pcppPaste(plannedListURL,
		"CPU: Ryzen 7 9800X3D  ($419.00 @ Amazon)",
		"Video Card: Radeon RX 9070 XT  ($549.99 @ Amazon)",
		"Storage: Samsung 990 Pro 2 TB  ($159.99 @ Amazon)",
	))
	assertStatus(t, rr, http.StatusSeeOther)
	if loc := rr.Header().Get("Location"); loc != machinePath(machineID, "") {
		t.Errorf("redirect = %q, want the machine page", loc)
	}

	cpu := app.partsNamed("alice", "Ryzen 7 9800X3D")[0]
	if cpu.PriceCents.Int64 != 41900 || cpu.PreviousPriceCents.Int64 != 44900 {
		t.Errorf("CPU price = %v (was %v), want 41900 (was 44900)", cpu.PriceCents, cpu.PreviousPriceCents)
	}
	gpu := app.partsNamed("alice", "Radeon RX 9070 XT")[0]
	if gpu.Status != partOwned || gpu.PriceCents.Int64 != 59900 || gpu.PreviousPriceCents.Valid {
		t.Errorf("bought GPU = %s at %v (was %v), want owned at the 59900 paid",
			gpu.Status, gpu.PriceCents, gpu.PreviousPriceCents)
	}
	ssds := app.partsNamed("alice", "Samsung 990 Pro 2 TB")
	if len(ssds) != 2 {
		t.Fatalf("got %d SSDs, want 2", len(ssds))
	}
	if ssds[0].PriceCents.Int64 != 15999 || ssds[0].MissingFromSourceAt.Valid {
		t.Errorf("first SSD = %v, missing %v; want 15999 and still listed", ssds[0].PriceCents, ssds[0].MissingFromSourceAt)
	}
	if ssds[1].PriceCents.Int64 != 16999 || !ssds[1].MissingFromSourceAt.Valid {
		t.Errorf("second SSD = %v, missing %v; want the old 16999 and marked missing",
			ssds[1].PriceCents, ssds[1].MissingFromSourceAt)
	}

	page := app.get(alice, machinePath(machineID, ""))
	assertStatus(t, page, http.StatusOK)
	assertContains(t, page, "Update prices", "checked today", `href="`+plannedListURL+`"`,
		"&darr; $30.00", "Not on its PCPartPicker list anymore")

	// An update with no change clears the last change, and a part back on
	// its list is no longer missing.
	assertStatus(t, app.updatePrices(alice, machineID, pcppPaste(plannedListURL,
		"CPU: Ryzen 7 9800X3D  ($419.00 @ Amazon)",
		"Storage: Samsung 990 Pro 2 TB  ($159.99 @ Amazon)",
		"Storage: Samsung 990 Pro 2 TB  ($159.99 @ Amazon)",
	)), http.StatusSeeOther)
	if cpu := app.partsNamed("alice", "Ryzen 7 9800X3D")[0]; cpu.PreviousPriceCents.Valid {
		t.Errorf("CPU previous price = %v after an unchanged update, want none", cpu.PreviousPriceCents)
	}
	second := app.partsNamed("alice", "Samsung 990 Pro 2 TB")[1]
	if second.MissingFromSourceAt.Valid || second.PriceCents.Int64 != 15999 || second.PreviousPriceCents.Int64 != 16999 {
		t.Errorf("second SSD = %v (was %v), missing %v; want 15999 (was 16999) and listed again",
			second.PriceCents, second.PreviousPriceCents, second.MissingFromSourceAt)
	}
}

// A list that shows no price for a part keeps the part's last price.
func TestUpdatePrices_NoPriceKeepsOld(t *testing.T) {
	app := newTestApp(t)
	alice := app.login("alice")
	machineID := app.importPlanned(alice)

	assertStatus(t, app.updatePrices(alice, machineID, pcppPaste(plannedListURL, "CPU: Ryzen 7 9800X3D")),
		http.StatusSeeOther)
	cpu := app.partsNamed("alice", "Ryzen 7 9800X3D")[0]
	if cpu.PriceCents.Int64 != 44900 || cpu.PreviousPriceCents.Valid || cpu.MissingFromSourceAt.Valid {
		t.Errorf("CPU = %v (was %v), missing %v; want 44900 unchanged and listed",
			cpu.PriceCents, cpu.PreviousPriceCents, cpu.MissingFromSourceAt)
	}
}

// Pastes that can't be matched to the machine's parts change nothing.
func TestUpdatePrices_RejectsOtherPastes(t *testing.T) {
	app := newTestApp(t)
	alice := app.login("alice")
	machineID := app.importPlanned(alice)

	tests := []struct {
		name, list, want string
	}{
		{"no parts", "PCPartPicker Part List: " + plannedListURL, "couldn&#39;t find any parts"},
		{"no first line", "CPU: Ryzen 7 9800X3D  ($1.00 @ Amazon)", "including its first line"},
		{"another list", pcppPaste("https://pcpartpicker.com/list/other", "CPU: Ryzen 7 9800X3D  ($1.00 @ Amazon)"),
			"came from that list"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			rr := app.updatePrices(alice, machineID, tt.list)
			assertStatus(t, rr, http.StatusBadRequest)
			assertContains(t, rr, tt.want)
			if cpu := app.partsNamed("alice", "Ryzen 7 9800X3D")[0]; cpu.PriceCents.Int64 != 44900 {
				t.Errorf("CPU price = %v, want 44900 unchanged", cpu.PriceCents)
			}
		})
	}
}

func TestUpdatePrices_OwnerOnly(t *testing.T) {
	app := newTestApp(t)
	alice := app.login("alice")
	bob := app.login("bob")
	machineID := app.importPlanned(alice)

	rr := app.updatePrices(bob, machineID, pcppPaste(plannedListURL, "CPU: Ryzen 7 9800X3D  ($1.00 @ Amazon)"))
	assertStatus(t, rr, http.StatusForbidden)
	if cpu := app.partsNamed("alice", "Ryzen 7 9800X3D")[0]; cpu.PriceCents.Int64 != 44900 {
		t.Errorf("CPU price = %v after bob's update, want 44900", cpu.PriceCents)
	}

	page := app.get(bob, machinePath(machineID, ""))
	assertStatus(t, page, http.StatusOK)
	assertNotContains(t, page, "Update prices", "Mark bought")
}

// A machine with no parts from a list has nothing to update.
func TestUpdatePrices_NothingFromAList(t *testing.T) {
	app := newTestApp(t)
	alice := app.login("alice")
	machineID := app.createMachine(alice, "Hand built")

	assertNotContains(t, app.get(alice, machinePath(machineID, "")), "Update prices")
	rr := app.updatePrices(alice, machineID, plannedList)
	assertStatus(t, rr, http.StatusBadRequest)
	assertContains(t, rr, "came from that list")
}

func TestMarkPartBought(t *testing.T) {
	app := newTestApp(t)
	alice := app.login("alice")
	bob := app.login("bob")
	machineID := app.importPlanned(alice)
	cpuSlot := slotOf(t, app.slots(machineID), "Ryzen 7 9800X3D")

	assertStatus(t, app.post(bob, slotPath(cpuSlot, "/part/bought"), nil), http.StatusForbidden)

	// No price paid given: the last known price stays. htmx gets the board,
	// with the CPU's card installed and its wire to draw in.
	rr := app.postHX(alice, slotPath(cpuSlot, "/part/bought"), url.Values{"price": {""}})
	assertStatus(t, rr, http.StatusOK)
	assertContains(t, rr, fmt.Sprintf(`class="slot-card k-owned" id="slot-%d"`, cpuSlot),
		fmt.Sprintf(`data-seated="%d"`, cpuSlot))
	cpu := app.partsNamed("alice", "Ryzen 7 9800X3D")[0]
	if cpu.Status != partOwned || cpu.PriceCents.Int64 != 44900 {
		t.Errorf("CPU = %s at %v, want owned at 44900", cpu.Status, cpu.PriceCents)
	}

	// It's bought now, so it can't be bought again.
	rr = app.postHX(alice, slotPath(cpuSlot, "/part/bought"), url.Values{"price": {"1"}})
	assertContains(t, rr, "Only your own parts that aren&#39;t bought yet can be marked bought.")
	if cpu := app.partsNamed("alice", "Ryzen 7 9800X3D")[0]; cpu.PriceCents.Int64 != 44900 {
		t.Errorf("CPU price = %v after a second purchase, want 44900", cpu.PriceCents)
	}
}

func TestMatchSourceRows(t *testing.T) {
	part := func(id int64, category, name string) db.Part {
		return db.Part{ID: id, Name: name, Category: optionalString(category)}
	}
	parts := []db.Part{
		part(1, "Storage", "Samsung 990 Pro"),
		part(2, "Storage", "Samsung 990 Pro"),
		part(3, "CPU", "Ryzen 7 9800X3D"),
		part(4, "Case", "Fractal North"),
	}
	rows := []csvRow{
		{category: "storage", name: " samsung 990 pro ", price: 150, hasPrice: true},
		{category: "CPU", name: "Ryzen 7 9800X3D", price: 400, hasPrice: true},
		{category: "Memory", name: "Fractal North"}, // same name, other type
	}
	got := matchSourceRows(parts, rows)
	found := func(i int) bool { return got[i].row != nil }
	if !found(0) || found(1) || !found(2) || found(3) {
		t.Errorf("matched = %v %v %v %v, want true false true false", found(0), found(1), found(2), found(3))
	}
	if found(2) && got[2].row.price != 400 {
		t.Errorf("CPU matched the row priced %v, want 400", got[2].row.price)
	}
}
